// GENERATED by scripts/gen-embedded-migrations.mjs — DO NOT EDIT.
// Run `bun run migrations:embed` after adding, removing or editing a migration.
//
// THE-578: the migration SQL is inlined here rather than read from disk so that provisioning works
// in the standalone binaries. `bun build --compile` bakes import.meta.url to the build-time path
// and embeds no .sql files, which made every published binary fail at module load with an ENOENT
// against the CI runner's directory. Inlining removes the filesystem from this path entirely, and
// keeps one code path across vitest, `bun run`, the npm dist build and --compile.
//
// Regenerating is drift-gated: `bun run migrations:embed:check` fails CI if this file does not
// match packages/server/src/migrations/.

/** Migration filename -> its SQL, for every file under packages/server/src/migrations. */
export const EMBEDDED_MIGRATIONS: Readonly<Record<string, string>> = {
  "20260519_001_initial.sql": "-- 20260519_001_initial.sql\n-- obsidian-tc V1.0 initial schema migration.\n--\n-- This migration creates all per-vault tables and indexes from a blank database.\n-- The migration runner sets the following PRAGMAs per-connection (not in the\n-- migration itself) before applying this file:\n--\n--   PRAGMA foreign_keys = ON;\n--   PRAGMA journal_mode = WAL;\n--\n-- Folds in the G2.4 B.2 schema delta on idempotency_keys (started_at +\n-- completed_at + nullable result/result_size for in-flight detection), since\n-- this initial migration has not yet been applied. See docs/G2.3-storage.md\n-- and docs/G2.4-security.md for the rationale.\n--\n-- The vec_chunks sqlite-vec virtual table is NOT created here because its\n-- embedding dimensions are runtime-bound per vault. The first embedding\n-- generation per vault creates vec_chunks and records itself as\n-- 20260519_002_vec_chunks_<DIMS> in schema_migrations.\n\n-- ----------------------------------------------------------------------------\n-- Migrations tracking\n-- ----------------------------------------------------------------------------\n\n-- Owned by the migration runner (ensureMigrationsTable pre-creates this before\n-- applying any migration); IF NOT EXISTS so applying this file via the runner\n-- or standalone never collides.\nCREATE TABLE IF NOT EXISTS schema_migrations (\n  version             TEXT PRIMARY KEY,\n  applied_at          INTEGER NOT NULL,\n  obsidian_tc_version TEXT NOT NULL,\n  duration_ms         INTEGER NOT NULL,\n  checksum            TEXT NOT NULL\n);\n\n-- ----------------------------------------------------------------------------\n-- Chunks\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE chunks (\n  id                TEXT PRIMARY KEY,\n  vault_id          TEXT NOT NULL,\n  path              TEXT NOT NULL,\n  chunk_index       TEXT NOT NULL,\n  headings          TEXT NOT NULL,\n  content           TEXT NOT NULL,\n  content_hash      TEXT NOT NULL,\n  token_count       INTEGER NOT NULL,\n  created_at        INTEGER NOT NULL,\n  updated_at        INTEGER NOT NULL,\n  cluster_id        INTEGER,\n  decay_score       REAL,\n  activation_count  INTEGER DEFAULT 0,\n  last_accessed_at  INTEGER\n);\n\nCREATE INDEX idx_chunks_vault_path ON chunks(vault_id, path);\nCREATE INDEX idx_chunks_hash       ON chunks(content_hash);\nCREATE INDEX idx_chunks_cluster    ON chunks(cluster_id) WHERE cluster_id IS NOT NULL;\n\n-- ----------------------------------------------------------------------------\n-- Chunk embeddings\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE chunk_embeddings (\n  chunk_id      TEXT NOT NULL,\n  model         TEXT NOT NULL,\n  dimensions    INTEGER NOT NULL,\n  embedding     BLOB NOT NULL,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  generated_at  INTEGER NOT NULL,\n  PRIMARY KEY (chunk_id, model),\n  FOREIGN KEY (chunk_id) REFERENCES chunks(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_chunk_embeddings_active ON chunk_embeddings(chunk_id) WHERE is_active = 1;\nCREATE INDEX idx_chunk_embeddings_model  ON chunk_embeddings(model);\n\n-- ----------------------------------------------------------------------------\n-- Workspace sessions\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE workspace_sessions (\n  id            TEXT PRIMARY KEY,\n  vault_id      TEXT NOT NULL,\n  caller        TEXT,\n  started_at    INTEGER NOT NULL,\n  ended_at      INTEGER,\n  trace_path    TEXT NOT NULL,\n  metadata_json TEXT\n);\n\nCREATE INDEX idx_workspace_sessions_vault   ON workspace_sessions(vault_id, started_at DESC);\nCREATE INDEX idx_workspace_sessions_unended ON workspace_sessions(ended_at) WHERE ended_at IS NULL;\n\n-- ----------------------------------------------------------------------------\n-- Capture queue\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE capture_queue (\n  id                TEXT PRIMARY KEY,\n  vault_id          TEXT NOT NULL,\n  title             TEXT,\n  content           TEXT NOT NULL,\n  tags              TEXT,\n  source            TEXT,\n  target_path_hint  TEXT,\n  captured_at       INTEGER NOT NULL,\n  committed_at      INTEGER,\n  committed_path    TEXT\n);\n\nCREATE INDEX idx_capture_uncommitted ON capture_queue(vault_id, captured_at DESC)\n  WHERE committed_at IS NULL;\n\n-- ----------------------------------------------------------------------------\n-- Memory entities (parents before children for FK satisfaction)\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE memory_entities (\n  id                TEXT PRIMARY KEY,\n  vault_id          TEXT NOT NULL,\n  entity_type       TEXT NOT NULL,\n  name              TEXT NOT NULL,\n  observations      TEXT NOT NULL,\n  materialize       INTEGER NOT NULL DEFAULT 1,\n  vault_path        TEXT,\n  created_at        INTEGER NOT NULL,\n  updated_at        INTEGER NOT NULL,\n  decay_score       REAL,\n  activation_count  INTEGER DEFAULT 0,\n  last_accessed_at  INTEGER\n);\n\nCREATE INDEX idx_memory_entities_vault_type ON memory_entities(vault_id, entity_type);\nCREATE INDEX idx_memory_entities_name       ON memory_entities(vault_id, name);\n\nCREATE TABLE memory_relations (\n  source_id      TEXT NOT NULL,\n  target_id      TEXT NOT NULL,\n  relation_type  TEXT NOT NULL,\n  created_at     INTEGER NOT NULL,\n  PRIMARY KEY (source_id, target_id, relation_type),\n  FOREIGN KEY (source_id) REFERENCES memory_entities(id) ON DELETE CASCADE,\n  FOREIGN KEY (target_id) REFERENCES memory_entities(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_memory_relations_target ON memory_relations(target_id);\n\n-- ----------------------------------------------------------------------------\n-- Idempotency keys\n-- ----------------------------------------------------------------------------\n-- Row lifecycle:\n--   1. INSERT on call start: started_at=now, completed_at=NULL,\n--      result=NULL, result_size=NULL, expires_at=now+ttl.\n--   2. On successful completion: UPDATE result, result_size, completed_at.\n--   3. Concurrent INSERT for same (vault_id, key) where completed_at IS NULL\n--      raises idempotency_in_flight.\n--   4. Sweep reaps rows where started_at+60000 < now AND completed_at IS NULL.\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE idempotency_keys (\n  vault_id      TEXT NOT NULL,\n  key           TEXT NOT NULL,\n  tool_name     TEXT NOT NULL,\n  args_hash     TEXT NOT NULL,\n  started_at    INTEGER NOT NULL,\n  completed_at  INTEGER,\n  result        BLOB,\n  result_size   INTEGER,\n  expires_at    INTEGER NOT NULL,\n  PRIMARY KEY (vault_id, key)\n);\n\nCREATE INDEX idx_idempotency_expires   ON idempotency_keys(expires_at);\nCREATE INDEX idx_idempotency_in_flight ON idempotency_keys(started_at) WHERE completed_at IS NULL;\n\n-- ----------------------------------------------------------------------------\n-- Elicit tokens\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE elicit_tokens (\n  token                 TEXT PRIMARY KEY,\n  vault_id              TEXT NOT NULL,\n  tool_name             TEXT NOT NULL,\n  args_hash             TEXT NOT NULL,\n  proposed_change_json  TEXT,\n  caller                TEXT,\n  created_at            INTEGER NOT NULL,\n  expires_at            INTEGER NOT NULL,\n  consumed_at           INTEGER\n);\n\nCREATE INDEX idx_elicit_tokens_expires ON elicit_tokens(expires_at);\n\n-- ----------------------------------------------------------------------------\n-- Event log\n-- ----------------------------------------------------------------------------\n\nCREATE TABLE event_log (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts           INTEGER NOT NULL,\n  vault_id     TEXT,\n  tool_name    TEXT,\n  caller       TEXT,\n  duration_ms  INTEGER,\n  result_size  INTEGER,\n  status       TEXT NOT NULL,\n  error_code   TEXT,\n  args_hash    TEXT,\n  event_type   TEXT\n);\n\nCREATE INDEX idx_event_log_ts      ON event_log(ts);\nCREATE INDEX idx_event_log_tool_ts ON event_log(tool_name, ts);\n\n-- ----------------------------------------------------------------------------\n-- Self-record this migration. The runner overrides duration_ms and checksum\n-- after execution with the measured values from this run.\n-- ----------------------------------------------------------------------------\n\nINSERT INTO schema_migrations (version, applied_at, obsidian_tc_version, duration_ms, checksum)\nVALUES ('20260519_001_initial', strftime('%s','now')*1000, '0.1.0', 0, 'sha256-placeholder');\n",
  "20260519_002_entity_unique.sql": "-- 20260519_002_entity_unique — F4: enforce the entity natural key\n-- (vault_id, entity_type, name) at the DB level to close the create_entity\n-- read-then-insert race. Pre-existing duplicates are merged into the earliest\n-- (MIN rowid) row. Relations are repointed onto the survivor BEFORE the dedup\n-- DELETE, so the ON DELETE CASCADE FKs do not drop edges that belonged to a\n-- duplicate (review #5); then the unique index is created.\n\n-- Repoint outgoing edges of a duplicate onto its surviving sibling. UPDATE OR IGNORE\n-- drops a repoint that would collide with an existing (source,target,type) edge.\nUPDATE OR IGNORE memory_relations\nSET source_id = (\n  SELECT keep.id\n  FROM memory_entities dup\n  JOIN memory_entities keep\n    ON keep.vault_id = dup.vault_id\n   AND keep.entity_type = dup.entity_type\n   AND keep.name = dup.name\n  WHERE dup.id = memory_relations.source_id\n  ORDER BY keep.rowid\n  LIMIT 1\n)\nWHERE source_id IN (\n  SELECT id FROM memory_entities\n  WHERE rowid NOT IN (SELECT MIN(rowid) FROM memory_entities GROUP BY vault_id, entity_type, name)\n);\n\n-- Repoint incoming edges likewise.\nUPDATE OR IGNORE memory_relations\nSET target_id = (\n  SELECT keep.id\n  FROM memory_entities dup\n  JOIN memory_entities keep\n    ON keep.vault_id = dup.vault_id\n   AND keep.entity_type = dup.entity_type\n   AND keep.name = dup.name\n  WHERE dup.id = memory_relations.target_id\n  ORDER BY keep.rowid\n  LIMIT 1\n)\nWHERE target_id IN (\n  SELECT id FROM memory_entities\n  WHERE rowid NOT IN (SELECT MIN(rowid) FROM memory_entities GROUP BY vault_id, entity_type, name)\n);\n\nDELETE FROM memory_entities\nWHERE rowid NOT IN (\n  SELECT MIN(rowid) FROM memory_entities GROUP BY vault_id, entity_type, name\n);\n\nCREATE UNIQUE INDEX idx_memory_entities_natural_key\n  ON memory_entities(vault_id, entity_type, name);\n",
  "20260626_001_experiential_init.sql": "-- 20260626_001_experiential_init.sql\n-- THE-233 (W-SCHEMA): the experiential tier -- a PHYSICALLY SEPARATE store (experiential.db),\n-- NOT a partition of cache.db. The membrane (see decision\n-- 2026-06-26-experiential-tier-write-on-gate): low-trust per-retrieval state lives in its\n-- own file so an injected / auto-captured episode can never FK into an authored atom,\n-- poisoning blast radius is capped at the store boundary, and a reset is a file truncate\n-- rather than a filtered delete. Because chunks live in cache.db, object_id / chunk_id\n-- reference chunk ids BY VALUE (no cross-file foreign key -- this is the membrane).\n--\n-- Holds only NON-RECONSTRUCTABLE keep-state: engram activation history + retrieval feedback.\n-- Authored chunks are re-indexed from the vault, never imported (thin-merge decision).\n-- Behavior-preserving port of KMS vault_object_state (migration 017) + chunk_retrievals (018).\n--\n-- PRAGMAs (foreign_keys, journal_mode = WAL) are set per-connection by the runtime.\n-- The migration runner pre-creates schema_migrations; it is not declared here.\n--\n-- TRIPWIRE: valid_from / valid_until are the EXISTING KMS 2-timestamp validity, loaded\n-- as-is. This is NOT the engine-build 4-timestamp bi-temporal substrate; no claim atoms,\n-- authoritative_claims, or derives_from (THE-235, downstream).\n\n-- ACT-R / engram activation state, one row per chunk (object).\nCREATE TABLE vault_object_state (\n  object_id               TEXT PRIMARY KEY,          -- chunk id, by value (membrane: no cross-file FK)\n  retrieval_strength      REAL,\n  storage_strength        REAL,\n  frequency               INTEGER NOT NULL DEFAULT 0,\n  last_accessed           INTEGER,\n  learned_at              INTEGER,\n  valid_from              INTEGER,                   -- existing KMS 2-timestamp validity (loaded as-is)\n  valid_until             INTEGER,\n  emotional_weight        REAL NOT NULL DEFAULT 5,   -- KMS default 5 (1-10 modulates ACT-R decay)\n  confidence              REAL,\n  injections              INTEGER NOT NULL DEFAULT 0,\n  hits                    INTEGER NOT NULL DEFAULT 0,\n  misses                  INTEGER NOT NULL DEFAULT 0,\n  last_hit_at             INTEGER,\n  cached_activation_score REAL,\n  last_computed_at        INTEGER\n);\n\nCREATE INDEX idx_vault_object_state_activation\n  ON vault_object_state(cached_activation_score)\n  WHERE cached_activation_score IS NOT NULL;\n\n-- Append-only retrieval event log; feeds the nightly activation recompute (sleep-time plane).\nCREATE TABLE chunk_retrievals (\n  id                TEXT PRIMARY KEY,                -- retrieval event id, by value\n  chunk_id          TEXT NOT NULL,                   -- chunk id, by value (membrane: no cross-file FK)\n  retrieved_at      INTEGER NOT NULL,\n  session_id        TEXT,\n  surface_type      TEXT,                            -- which surface / client retrieved it\n  query_text        TEXT,\n  rank_in_results   INTEGER,\n  rerank_score      REAL,                            -- rerank passthrough score (D1); was KMS cohere_score\n  cited_in_response INTEGER,                         -- nullable 0/1\n  citation_score    REAL,\n  feedback          INTEGER                          -- -1 | 0 | +1\n);\n\nCREATE INDEX idx_chunk_retrievals_chunk   ON chunk_retrievals(chunk_id, retrieved_at DESC);\nCREATE INDEX idx_chunk_retrievals_session ON chunk_retrievals(session_id) WHERE session_id IS NOT NULL;\n",
  "20260626_001_vault_edges.sql": "-- 20260626_001_vault_edges.sql\n-- THE-233 (W-SCHEMA): wikilink edge graph for GraphRAG.\n--\n-- The ported vault_graph_expand walks this edge table (KMS migrations 005/011/013).\n-- Edges are authored / derived from vault wikilinks, so they live in the main cache.db\n-- alongside chunks. Path-based (a wikilink is note -> note); the graph walk joins edges\n-- to chunks by path. Behavior-preserving port of the KMS vault_edges shape (Postgres)\n-- onto SQLite. SQLite has full recursive CTEs, so the expand walk ports directly; only\n-- the pgvector distance operator becomes a sqlite-vec / in-process call (retrieval slice).\n--\n-- PRAGMAs (foreign_keys, journal_mode = WAL) are set per-connection by the runtime.\n--\n-- TRIPWIRE: plain graph structure only. No claim atoms, authoritative_claims,\n-- derives_from, or bi-temporal columns -- that is the engine-build typed-atom substrate\n-- (THE-235), downstream of this merge.\n\nCREATE TABLE vault_edges (\n  source_path  TEXT NOT NULL,                       -- vault-relative note path (edge tail)\n  target_path  TEXT NOT NULL,                       -- vault-relative note path (edge head)\n  edge_type    TEXT NOT NULL,                       -- relation verb, e.g. \"links_to\" | \"embed\" | \"tag\"\n  edge_kind    TEXT NOT NULL DEFAULT 'literal',     -- 'literal' (wikilink) | 'virtual' (cosine neighbor)\n  provenance   TEXT,                                -- how the edge was derived, e.g. \"wikilink\" | \"graph_expand\"\n  created_at   INTEGER NOT NULL,\n  updated_at   INTEGER NOT NULL\n);\n\n-- Dedup identical edges regardless of insert order (mirrors KMS unique(source, target, type)).\nCREATE UNIQUE INDEX idx_vault_edges_unique ON vault_edges(source_path, target_path, edge_type);\nCREATE INDEX idx_vault_edges_source ON vault_edges(source_path);\nCREATE INDEX idx_vault_edges_target ON vault_edges(target_path);\nCREATE INDEX idx_vault_edges_kind   ON vault_edges(edge_kind);\n",
  "20260626_002_plane.sql": "-- 20260626_002_plane.sql\n-- THE-233 W-WORKERS: sleep-time consolidation plane state tables. Committed here but NOT yet\n-- wired into the cli.ts migrate chain — that registration lands in the integration slice\n-- (Batch 4), alongside W-SCHEMA's vault_edges/experiential migrations. The plane jobs operate\n-- on these tables; the unit tests provision them directly.\n--\n-- PRAGMAs (foreign_keys, journal_mode = WAL) are set per-connection by the runtime.\n-- TRIPWIRE: lifecycle/state tables only. No claim atoms, authoritative_claims, derives_from,\n-- or 4-timestamp bi-temporal columns (detected_at/resolved_at is the existing KMS 2-timestamp\n-- flag lifecycle, not the engine-build substrate).\n\n-- Contradiction flags (contradiction job; was KMS contradictions table). Flag-only lifecycle.\nCREATE TABLE contradictions (\n  id                   TEXT PRIMARY KEY,\n  source_chunk_id      TEXT NOT NULL,\n  source_path          TEXT NOT NULL,\n  conflict_chunk_id    TEXT NOT NULL,\n  conflict_path        TEXT NOT NULL,\n  source_content_sha   TEXT NOT NULL,\n  conflict_content_sha TEXT NOT NULL,\n  cosine_similarity    REAL,\n  judge_verdict        TEXT NOT NULL,        -- 'contradiction' | 'tension'\n  judge_rationale      TEXT,\n  judge_model          TEXT,                 -- resolved gateway model (attestation)\n  status               TEXT NOT NULL DEFAULT 'open',\n  detected_at          INTEGER NOT NULL,\n  resolved_at          INTEGER\n);\n\n-- Dedup a pair regardless of which side was the new chunk (mirrors KMS unique constraint).\nCREATE UNIQUE INDEX idx_contradictions_pair ON contradictions(source_content_sha, conflict_content_sha);\nCREATE INDEX idx_contradictions_status ON contradictions(status, detected_at DESC);\n\n-- Weekly synthesis records (synthesis job; was KMS syntheses table). One row per ISO week.\nCREATE TABLE syntheses (\n  iso_year      INTEGER NOT NULL,\n  iso_week      INTEGER NOT NULL,\n  generated_at  INTEGER NOT NULL,\n  cluster_count INTEGER NOT NULL,\n  pattern_count INTEGER NOT NULL,\n  clusters      TEXT NOT NULL,               -- JSON\n  patterns      TEXT NOT NULL,               -- JSON\n  judge_model   TEXT,\n  PRIMARY KEY (iso_year, iso_week)\n);\n\n-- Health audit reports (audit job; was KMS audit_reports/audit_flags collapsed).\nCREATE TABLE audit_reports (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  report_type TEXT NOT NULL,\n  created_at  INTEGER NOT NULL,\n  has_issues  INTEGER NOT NULL,\n  summary     TEXT,\n  report      TEXT NOT NULL                  -- JSON\n);\n\nCREATE INDEX idx_audit_reports_created ON audit_reports(created_at DESC);\n\n-- Plane run log (observability for the local job runner).\nCREATE TABLE job_runs (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  job         TEXT NOT NULL,\n  started_at  INTEGER NOT NULL,\n  finished_at INTEGER,\n  ok          INTEGER NOT NULL,\n  detail      TEXT                           -- JSON\n);\n\nCREATE INDEX idx_job_runs_job ON job_runs(job, started_at DESC);\n",
  "20260702_001_notes.sql": "-- THE-291: per-note metadata backing the lexical/metadata index (list_tags, list_properties,\n-- find_notes_by_*, search_text acceleration). notes_fts (FTS5, trigram) is runtime-provisioned\n-- by ensureNotesFts (search/fts.ts) exactly like vec_chunks — deliberately NOT in this chain,\n-- so the versioned migrations apply unchanged on an adapter built without FTS5.\nCREATE TABLE IF NOT EXISTS notes (\n  vault_id     TEXT NOT NULL,\n  path         TEXT NOT NULL,\n  title        TEXT NOT NULL,\n  tags         TEXT NOT NULL,           -- JSON array (noteTags(raw).all)\n  frontmatter  TEXT,                    -- JSON object; NULL when absent or unserializable\n  content_hash TEXT NOT NULL,           -- contentHash(raw) — backfill/staleness key\n  mtime        INTEGER NOT NULL,\n  size         INTEGER NOT NULL,\n  indexed_at   INTEGER NOT NULL,\n  PRIMARY KEY (vault_id, path)\n);\nCREATE INDEX IF NOT EXISTS idx_notes_hash ON notes(content_hash);\n",
  "20260703_001_vault_edges_vault_id.sql": "-- 20260703_001_vault_edges_vault_id.sql\n-- THE-310: add vault_id to vault_edges so multi-vault GraphRAG is isolated.\n--\n-- vault_edges (20260626_001) predates the shared cache.db logical vault_id isolation that\n-- chunks/notes/embeddings carry. Without it, reconcileVaultEdges() -- a full-state reconcile\n-- run once per index_vault pass -- deletes another vault's wikilink edges, and the graph walk\n-- (graph_expand) crosses vaults. Edges are a rebuildable derived cache, so rather than backfill\n-- an unknowable vault_id we clear the unscoped rows; the next index_vault per vault repopulates\n-- them scoped. The unique index is recreated to include vault_id so two vaults can hold the same\n-- path-pair edge; a vault_id index backs the scoped SELECT/DELETE and the graph walk.\n\nDELETE FROM vault_edges;\nALTER TABLE vault_edges ADD COLUMN vault_id TEXT NOT NULL DEFAULT '';\nDROP INDEX IF EXISTS idx_vault_edges_unique;\nCREATE UNIQUE INDEX idx_vault_edges_unique ON vault_edges(vault_id, source_path, target_path, edge_type);\nCREATE INDEX IF NOT EXISTS idx_vault_edges_vault ON vault_edges(vault_id);\n",
  "20260709_001_snapshots.sql": "-- THE-374: point-in-time note snapshots for restore_note. Content-addressed blob store\n-- (SHA-256 dedup per vault) + a per-note snapshot ledger. Auto-captured on destructive\n-- writes when config.snapshots.enabled; read back / rolled back via the M1 snapshot tools.\nCREATE TABLE IF NOT EXISTS snapshot_blobs (\n  vault_id TEXT NOT NULL,\n  hash     TEXT NOT NULL,           -- contentHash(content)\n  content  TEXT NOT NULL,           -- full note bytes at capture time\n  size     INTEGER NOT NULL,\n  PRIMARY KEY (vault_id, hash)\n);\nCREATE TABLE IF NOT EXISTS note_snapshots (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  vault_id   TEXT NOT NULL,\n  path       TEXT NOT NULL,\n  hash       TEXT NOT NULL,         -- -> snapshot_blobs(vault_id, hash)\n  op         TEXT NOT NULL,         -- capturing op: write_note|append_note|patch_note|delete_note|move_note|copy_note|update_frontmatter|restore_note|manual\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_note_snapshots_path ON note_snapshots(vault_id, path, id);\n",
  "20260711_001_experiential_outcome.sql": "-- 20260711_001_experiential_outcome.sql\n-- THE-230: the outcome axis on chunk_retrievals — \"did acting on this retrieval lead to a\n-- good outcome\" (-1 | 0 | +1, nullable), DISTINCT from `feedback` (relevance: \"was this the\n-- right chunk\"). A chunk can be perfectly relevant and still lead down a dead end; Brain's\n-- dead-end-source avoidance needs the second axis. Stamped by downstream writers (THE-170\n-- citation gate, session-close outcome pass); the ACT-R recompute folds it into the event\n-- weight the same bounded way it folds feedback.\nALTER TABLE chunk_retrievals ADD COLUMN outcome INTEGER;\n",
  "20260711_002_agent_episodes.sql": "-- 20260711_002_agent_episodes.sql\n-- THE-228: agent_episodes — the auto-capture work-memory log (THE-227 epic), in the SEPARATE\n-- experiential store per the membrane. Capture-everything on the ACTION axis: every dispatch\n-- outcome lands as one append-only row via the registry onEpisode hook. The CONTENT axis\n-- (raw args) is config-gated (experiential.captureContent, default OFF until THE-238's\n-- poisoning defense lands); when on, args are secret-scanned + size-capped before storage.\n--\n-- Write-on controls (2026-06-26 gate decision):\n--   * `blocked`      retrieval-time tombstone (control 1); `work_forget` surfaces it (THE-229).\n--   * `eligibility`  evaluator selective-addition stamp (control 2) — rows are born 'pending'\n--                    and become retrievable only when the sleep-time evaluator marks them\n--                    'eligible'; the log stays complete while retrieval-USE is gated.\n--   * valid_from / valid_until  bi-temporal invalidation honored by readers (control 3).\n--   * `caller` / `session_id`   self-carried attribution at write (constraint 4; THE-160 is\n--                    explicitly NOT a dependency).\nCREATE TABLE agent_episodes (\n  id            TEXT PRIMARY KEY,            -- ep_<hex>\n  ts            INTEGER NOT NULL,            -- ms epoch, capture time\n  vault_id      TEXT,\n  session_id    TEXT,                        -- active workspace session, else NULL\n  caller        TEXT,                        -- principal (attribution at write)\n  channel       TEXT NOT NULL,               -- write channel: 'dispatch' (v1); 'ambient'/'import' later\n  episode_type  TEXT NOT NULL,               -- 'tool_call' (v1)\n  tool          TEXT,\n  status        TEXT NOT NULL,               -- ok | error | skipped (dispatch outcome)\n  error_code    TEXT,\n  duration_ms   INTEGER,\n  result_size   INTEGER,\n  args_hash     TEXT,\n  args_json     TEXT,                        -- content axis: NULL unless captureContent; scanned + capped\n  secret_scan   TEXT,                        -- 'off' | 'clean' | 'redacted:<n>'\n  summary       TEXT,                        -- gist, filled at consolidation (THE-222); NULL at capture\n  tags          TEXT,                        -- JSON array\n  outcome       INTEGER,                     -- -1 | 0 | +1 (parity with chunk_retrievals outcome axis)\n  eligibility   TEXT NOT NULL DEFAULT 'pending',  -- pending | eligible | ineligible\n  trust         REAL,                        -- provenance trust (THE-238 channel policy)\n  blocked       INTEGER NOT NULL DEFAULT 0,  -- tombstone\n  valid_from    INTEGER,\n  valid_until   INTEGER,\n  prev_id       TEXT                         -- previous episode by same caller (temporal chain)\n);\n\nCREATE INDEX idx_agent_episodes_ts       ON agent_episodes(ts DESC);\nCREATE INDEX idx_agent_episodes_session  ON agent_episodes(session_id) WHERE session_id IS NOT NULL;\nCREATE INDEX idx_agent_episodes_caller   ON agent_episodes(caller, ts DESC);\nCREATE INDEX idx_agent_episodes_retrieve ON agent_episodes(eligibility, blocked, ts DESC);\n",
  "20260712_001_preference_profile.sql": "-- 20260712_001_preference_profile.sql\n-- THE-222: the versioned preference profile — the LongMemEval preference-class mechanism,\n-- updated ONLY by typed deltas (the ACE constraint folded from THE-232: add / strengthen /\n-- weaken / retract with weight counters, never monolithic regeneration). preference_deltas is\n-- the append-only audit of every applied delta; preference_profile is the current rollup the\n-- readers consume (weight > 0). Lives in the experiential store with the rest of the derived\n-- work-memory tier.\nCREATE TABLE preference_profile (\n  key         TEXT PRIMARY KEY,\n  value       TEXT NOT NULL,\n  weight      REAL NOT NULL DEFAULT 1.0,   -- confidence counter: capped [0, 5]; 0 = retracted\n  version     INTEGER NOT NULL,            -- monotonic batch version of the last touching delta\n  updated_at  INTEGER NOT NULL,\n  provenance  TEXT                         -- evidence gist from the extracting pass\n);\n\nCREATE TABLE preference_deltas (\n  id       INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts       INTEGER NOT NULL,\n  key      TEXT NOT NULL,\n  op       TEXT NOT NULL CHECK (op IN ('add','strengthen','weaken','retract')),\n  value    TEXT,\n  evidence TEXT,\n  version  INTEGER NOT NULL\n);\n\nCREATE INDEX idx_preference_deltas_version ON preference_deltas(version);\n",
  "20260712_002_access_views.sql": "-- 20260712_002_access_views.sql\n-- THE-44 (local re-scope, 2026-07-11 flywheel decision): derive-don't-mutate. The original\n-- ticket added last_accessed_at / access_count columns to the chunk store; the serve-path\n-- retrieval log (THE-230) already carries every access event, so the instrumentation is a\n-- VIEW over chunk_retrievals — no writer mutates the authored store, and the numbers can\n-- never drift from the log they derive from. linked_issue_id became the `linear:` frontmatter\n-- convention on notes (notes.frontmatter is queryable JSON), not a column.\nCREATE VIEW chunk_access_stats AS\nSELECT\n  chunk_id,\n  COUNT(*)                                                   AS access_count,\n  MAX(retrieved_at)                                          AS last_accessed_at,\n  SUM(CASE WHEN cited_in_response = 1 THEN 1 ELSE 0 END)     AS citations,\n  SUM(CASE WHEN outcome = 1 THEN 1 WHEN outcome = -1 THEN -1 ELSE 0 END) AS outcome_balance\nFROM chunk_retrievals\nGROUP BY chunk_id;\n",
  "20260712_003_forget_log.sql": "-- 20260712_003_forget_log.sql\n-- THE-239: the hash-chained forget audit log. Every dependency-aware deletion (episode or\n-- note) appends one row whose hash covers the previous row's hash + this row's fields —\n-- tampering with or removing any entry breaks the chain (verifyForgetLog walks it). This is\n-- the \"tombstone + audit\" half of the GDPR / EU AI Act policy tension: the log records THAT\n-- something was forgotten and what cascaded, never the forgotten content itself.\nCREATE TABLE forget_log (\n  seq       INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts        INTEGER NOT NULL,\n  kind      TEXT NOT NULL CHECK (kind IN ('episode', 'note')),\n  target    TEXT NOT NULL,             -- episode id or vault-relative note path\n  mode      TEXT NOT NULL CHECK (mode IN ('tombstone', 'erase')),\n  details   TEXT,                      -- JSON cascade summary (counts + report-only findings)\n  prev_hash TEXT NOT NULL,\n  hash      TEXT NOT NULL\n);\n",
  "20260713_001_vault_edges_derived.sql": "-- 20260713_001_vault_edges_derived.sql\n-- Graph densification (graphify spec-donor port): derived edges beyond the literal wikilink layer.\n-- See docs/plans/2026-07-13-graph-densification.md.\n--\n-- Adds two nullable columns so derived edges (edge_kind 'virtual'/'derived') can carry a confidence\n-- and a content fingerprint of their cited source. Existing literal `links_to`/`unresolved` rows keep\n-- NULL for both (the wikilink layer is confidence 1.0 by construction, no fingerprint). Nullable\n-- ADD COLUMN is a rewrite-free, backfill-free migration; the reconcile paths write the columns\n-- explicitly. The unique index already keys on edge_type, so derived edge_types (shared_tag,\n-- similar_to, semantically_similar_to) coexist with the literal rows without a schema change.\n--\n-- source_fingerprint: a hash of the cited source note's content at extraction time. A derived edge\n-- whose source later changes self-flags \"stale, re-verify\" (graphify content-fingerprint pattern)\n-- rather than presenting as authoritative. Never read by the graph walk; carried for the staleness\n-- sweep + audits.\n--\n-- TRIPWIRE: still plain graph structure. No claim atoms / authoritative_claims / derives_from — that\n-- is the THE-235 typed-atom substrate, downstream of this.\n\nALTER TABLE vault_edges ADD COLUMN confidence REAL;\nALTER TABLE vault_edges ADD COLUMN source_fingerprint TEXT;\n",
  "20260719_001_chunks_body_sha.sql": "-- 20260719_001_chunks_body_sha.sql\n-- Cross-path duplicate-embedding dedup (port of KMS migrations/014_vault_chunks_body_sha).\n--\n-- Why a SECOND hash. content_hash is contentHash() over the chunk's ENRICHED embed text\n-- (search/chunk.ts enrichChunkText prepends the note title + heading breadcrumb before the body),\n-- and the chunk id itself is keyed on (vault, path, index). Both are path-salted by construction, so\n-- the SAME body pasted at two different paths produces different content_hashes AND different chunk\n-- ids — it embeds + stores its own vector twice. body_sha is contentHash() over the RAW chunk body\n-- alone (the `content` column, PRE-enrichment), which is the key cross-path embedding dedup needs:\n-- identical bodies at different paths collide here, so the indexer can embed the first walked copy\n-- and reuse/skip the embedding for the rest.\n--\n-- Additive + backfill-tolerant. A nullable ADD COLUMN is rewrite-free and needs no backfill — rows\n-- written before this migration keep NULL. The indexer fills body_sha going forward and DEGRADES\n-- GRACEFULLY when the column is absent (an older cache.db, or a bare fixture): the per-run dedup\n-- registry is in-memory, so cross-path dedup still works; only the persisted column write is skipped\n-- (mirrors the hasDerivedEdgeColumns guard in search/indexer.ts). Inert for retrieval — body_sha is\n-- read by no ranking path; it is carried for the dedup fingerprint + audits.\n\nALTER TABLE chunks ADD COLUMN body_sha TEXT;\nCREATE INDEX IF NOT EXISTS chunks_body_sha ON chunks (body_sha);\n",
  "20260722_001_chunks_dedup_index.sql": "-- THE-502: composite index for the cross-path dedup lookup.\n--\n-- copyDedupVectors (search/indexer.ts) resolves a reusable embedding with\n--   WHERE c.vault_id = ? AND c.body_sha = ? AND c.content_hash = ?\n-- but the schema only indexed body_sha (chunks_body_sha, migration 20260719_001). SQLite therefore\n-- found candidates by body_sha and filtered vault_id + content_hash row by row — exactly the wrong\n-- shape for a duplicate-heavy vault (templates, canonical notes), which is the case cross-path\n-- dedup exists to serve.\n--\n-- Column order matches the predicate's selectivity: vault_id narrows to one vault, body_sha to one\n-- body, content_hash to one chunking of it.\n--\n-- chunks_body_sha is deliberately KEPT: it still serves lookups that know only the body hash.\nCREATE INDEX IF NOT EXISTS idx_chunks_dedup ON chunks (vault_id, body_sha, content_hash);\n",
  "20260723_001_activation_watermark.sql": "-- 20260723_001_activation_watermark.sql\n-- THE-461: incremental ACT-R activation recompute. recomputeActivation read the ENTIRE\n-- chunk_retrievals log on every timer pass; that full-history scan grows unbounded with retrieval\n-- volume and competes with interactive dispatch. A one-row watermark records the max\n-- chunk_retrievals rowid already folded into the cached activation scores, so an incremental pass\n-- reconciles only chunks with events past it. chunk_retrievals is append-only (kept for\n-- audit/research), so rowid is monotonic and race-free as the watermark. The exact ACT-R formula is\n-- unchanged — this avoids the rescan, not the math (approximations like Petrov 2006 would change\n-- retrieval behaviour and are out of scope). Watermark 0 (the seed) makes the first pass a full one.\nCREATE TABLE IF NOT EXISTS activation_state (\n  id        INTEGER PRIMARY KEY CHECK (id = 1),\n  watermark INTEGER NOT NULL DEFAULT 0\n);\nINSERT INTO activation_state (id, watermark) VALUES (1, 0)\n  ON CONFLICT(id) DO NOTHING;\n",
  "20260723_001_vault_generation.sql": "-- 20260723_001_vault_generation.sql\n-- THE-496: a monotonic per-vault generation counter, bumped on every mutation that can change query\n-- results (chunk upserts/deletes, edge/densification changes — all of which flow through the index\n-- write paths). It is one half of the query-cache key (THE-497); the other half is the per-caller ACL\n-- fingerprint (aclFingerprint, in code). Content changes bump the generation; ACL/scope changes are\n-- captured by the fingerprint, so together they invalidate every result-affecting change. A missed\n-- bump would silently serve stale cached results, so the bump lives INSIDE each index write\n-- transaction. Absent row reads as generation 0.\nCREATE TABLE IF NOT EXISTS vault_generation (\n  vault_id   TEXT PRIMARY KEY,\n  generation INTEGER NOT NULL DEFAULT 0\n);\n",
  "20260723_002_jobs.sql": "-- 20260723_002_jobs.sql\n-- THE-517: a durable job-queue record. Replaces the split in-memory/DB retry state that THE-462\n-- left in `job_schedule` (a per-JOB-NAME row for the four periodic sweeps) with a per-JOB-INSTANCE\n-- record for one-shot/queued work: attempt count, backoff, and lease all live in this table and\n-- ONLY here — a crashed process has nothing in memory to disagree with it.\n--\n-- state machine: queued -> running -> {complete | retrying | failed}; retrying -> running (once\n-- next_attempt_at is due); running -> running (lease reclaimed by a new owner past\n-- lease_expires_at, which is how crash recovery works — see job-queue.ts claim()).\n--\n-- class is the bounded-concurrency bucket (defaults to type; several types can share a class).\n-- idempotency_key is UNIQUE (NULLs are distinct in SQLite, so non-deduped jobs are unaffected);\n-- enqueue() upserts against it so the same key enqueued twice yields the same row.\nCREATE TABLE IF NOT EXISTS jobs (\n  id                TEXT PRIMARY KEY,\n  type              TEXT NOT NULL,\n  class             TEXT NOT NULL,\n  state             TEXT NOT NULL DEFAULT 'queued'\n                      CHECK (state IN ('queued', 'running', 'retrying', 'complete', 'failed')),\n  attempt           INTEGER NOT NULL DEFAULT 0,\n  max_attempts      INTEGER NOT NULL DEFAULT 5,\n  next_attempt_at   INTEGER,\n  lease_owner       TEXT,\n  lease_expires_at  INTEGER,\n  cancel_requested  INTEGER NOT NULL DEFAULT 0,\n  checkpoint        TEXT,\n  payload           TEXT,\n  idempotency_key   TEXT,\n  last_error        TEXT,\n  created_at        INTEGER NOT NULL,\n  updated_at        INTEGER NOT NULL\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS jobs_idempotency_key ON jobs (idempotency_key)\n  WHERE idempotency_key IS NOT NULL;\n\n-- Claim's due-scan filters on state and orders by due time; this covers both branches\n-- (queued jobs have next_attempt_at NULL and sort by created_at via COALESCE at query time).\nCREATE INDEX IF NOT EXISTS jobs_claim_scan ON jobs (state, class, next_attempt_at);\n",
  "20260724_001_chunk_retrievals_caller.sql": "-- THE-568 (P1.7 follow-up): per-caller ownership of retrieval feedback. chunk_retrievals carried\n-- only session_id, so feedback ownership was session-granular. Add caller so record_retrieval_feedback\n-- can gate on the calling principal, mirroring the agent_episodes partition.\nALTER TABLE chunk_retrievals ADD COLUMN caller TEXT;\nCREATE INDEX IF NOT EXISTS idx_chunk_retrievals_caller ON chunk_retrievals(caller) WHERE caller IS NOT NULL;\n",
  "20260724_001_plane_vault_id.sql": "-- 20260724_001_plane_vault_id.sql\n-- THE-563: namespace the derived-cognition plane. contradictions + syntheses predate the shared\n-- cache.db vault_id isolation that chunks/notes/embeddings carry. Both are REGENERABLE derived\n-- caches (contradictions re-flag on the next reindex; syntheses regenerate on the next weekly run)\n-- and their historical vault is UNRECOVERABLE (a contradiction may pair chunks from two vaults; a\n-- synthesis blended every vault). So we PURGE the unscoped rows rather than backfill a guess -- the\n-- same disposition THE-310 (20260703_001) took for vault_edges. Writers repopulate scoped.\n\n-- contradictions: purge, add vault_id, re-scope the pair-dedup index to include it so two vaults may\n-- hold the same content-sha pair. NOT NULL DEFAULT '' satisfies the ALTER on the emptied table; no\n-- row is ever written with '' (every writer supplies a real vault_id).\nDELETE FROM contradictions;\nALTER TABLE contradictions ADD COLUMN vault_id TEXT NOT NULL DEFAULT '';\nDROP INDEX IF EXISTS idx_contradictions_pair;\nCREATE UNIQUE INDEX idx_contradictions_pair\n  ON contradictions(vault_id, source_content_sha, conflict_content_sha);\nCREATE INDEX IF NOT EXISTS idx_contradictions_vault ON contradictions(vault_id);\n\n-- syntheses: a composite PK cannot be altered in place. DROP discards the unscoped rows (purge) and\n-- the table is recreated with vault_id leading the PK so each vault owns one row per ISO week.\nDROP TABLE syntheses;\nCREATE TABLE syntheses (\n  vault_id      TEXT NOT NULL,\n  iso_year      INTEGER NOT NULL,\n  iso_week      INTEGER NOT NULL,\n  generated_at  INTEGER NOT NULL,\n  cluster_count INTEGER NOT NULL,\n  pattern_count INTEGER NOT NULL,\n  clusters      TEXT NOT NULL,\n  patterns      TEXT NOT NULL,\n  judge_model   TEXT,\n  PRIMARY KEY (vault_id, iso_year, iso_week)\n);\n",
  "20260724_002_idempotency_state.sql": "-- THE-562 #13 (THE-413 residual): make the idempotency claim state machine explicit. Prior code\n-- inferred state from completed_at (+ an overflow sentinel), so a post-effect fault could not be\n-- distinguished from a pre-effect one and the claim was deleted → a retry re-ran a committed effect.\n-- states: in_flight (claimed) -> effect_committed (handler returned, effect may be durable, response\n-- not recorded) -> completed (response/overflow recorded) | indeterminate (post-effect fault).\nALTER TABLE idempotency_keys ADD COLUMN state TEXT NOT NULL DEFAULT 'in_flight';\n\n-- Back-fill: any pre-existing finished row is 'completed'. In-flight rows stay 'in_flight'\n-- (they predate the marker; reclaim treats them as before — acceptable, they are near-expiry).\nUPDATE idempotency_keys SET state = 'completed' WHERE completed_at IS NOT NULL;\n",
  "20260725_001_retrieval_policy.sql": "-- THE-538: retrieval POLICY provenance. chunk_retrievals records what was returned and where it\n-- ranked, but nothing about HOW it was ranked — GraphSearchResult.source (seed/expansion/lexical/\n-- sparse/temporal) was discarded at every call site, and the fusion configuration was never\n-- recorded at all. Without those, no outcome in chunk_retrievals can be attributed to a fusion\n-- configuration, which makes any later weight-learning work not merely noisy but UNIDENTIFIABLE.\n--\n-- Pure instrumentation: this migration adds no exploration arm and randomizes nothing. `arm` is\n-- always 'control' and `propensity` always 1.0 today. `propensity` is stored anyway because it is\n-- the one field that CANNOT be reconstructed after the fact — the probability with which the\n-- serving policy chose this configuration is only knowable at decision time, and its absence is\n-- exactly what would make a later offline fit unsound. Logging a constant 1.0 now costs 8 bytes a\n-- row and keeps that door open.\n--\n-- GROWTH: one row per SEARCH CALL, against chunk_retrievals' one row per RETURNED CHUNK — so this\n-- table grows ~1/K as fast as the log it annotates (K = top-K, typically 10–30). Both are\n-- deliberately append-only and kept for audit/research (see 20260723_001_activation_watermark.sql),\n-- and neither has a retention owner. At a heavy 1,000 searches/day this table adds roughly 0.1 MB\n-- and chunk_retrievals roughly 3 MB per day. Unbounded log growth is tracked separately; this\n-- migration makes the smaller half of it explicit rather than introducing a new unowned cost.\n\nCREATE TABLE retrieval_policy (\n  event_group   TEXT PRIMARY KEY,   -- one id per search call; stamped onto that call's chunk_retrievals rows\n  ts            INTEGER NOT NULL,\n  vault_id      TEXT,               -- chunk_retrievals has no vault_id; it is carried here\n  surface_type  TEXT,               -- the serve surface (tool name), mirroring chunk_retrievals\n  policy_id     TEXT,               -- 'static' | 'idf' | 'learned:v3'\n  arm           TEXT,               -- always 'control' in THE-538\n  dense_w       REAL,\n  lex_w         REAL,\n  sparse_w      REAL,\n  fusion_mode   TEXT,\n  rrf_k         INTEGER,\n  route_class   TEXT,\n  propensity    REAL                -- always 1.0 here; see the header on why it is stored anyway\n);\n\nCREATE INDEX idx_retrieval_policy_ts ON retrieval_policy(ts DESC);\nCREATE INDEX idx_retrieval_policy_vault ON retrieval_policy(vault_id) WHERE vault_id IS NOT NULL;\n\n-- Nullable ADD COLUMN is rewrite-free and back-compatible (the body_sha precedent,\n-- 20260719_001_chunks_body_sha.sql): an existing experiential.db migrates forward in place and its\n-- pre-THE-538 rows simply carry NULL in both columns.\nALTER TABLE chunk_retrievals ADD COLUMN event_group TEXT;\nALTER TABLE chunk_retrievals ADD COLUMN stream_source TEXT;\n\nCREATE INDEX IF NOT EXISTS idx_chunk_retrievals_event_group\n  ON chunk_retrievals(event_group) WHERE event_group IS NOT NULL;\n",
  "20260725_002_note_quality.sql": "-- THE-537: the note_quality rollup — one derived row per (vault_id, path).\n--\n-- Quality signals were scattered across two stores and three access patterns, with no place to ask\n-- \"which notes are duplicated / orphaned / stale / contradicted\". chunks.body_sha in particular is a\n-- fingerprint with NO report surface at all — its own migration says so (20260719_001: \"Inert for\n-- retrieval — body_sha is read by no ranking path\"). This is that surface.\n--\n-- It lives in experiential.db, not cache.db, because it is DERIVED, RESETTABLE, and mixes low-trust\n-- usage telemetry with authored metadata — the membrane rule. Keys by value, no cross-file FK,\n-- matching the store's existing contract.\n--\n-- RAW COMPONENTS ARE STORED ALONGSIDE THE SCORE, deliberately. A single opaque number is\n-- unreviewable; `score_version` plus the raw columns let the formula change without re-deriving\n-- history or lying about old rows. `flags` is what a human actually reads.\n--\n-- quality_score IS NULL — not 0, not 0.5 — WHEN EVIDENCE IS INSUFFICIENT. Citations are near-zero\n-- in practice today, so a naive score would rank the entire vault as low-quality and be worse than\n-- nothing. \"Unmeasured\" and \"bad\" must stay distinguishable, and only NULL does that.\n--\n-- NOT THE RANKER. Nothing in the retrieval path reads this table; feeding quality_score into\n-- fusion would be a ranking change needing its own eval gate. A test greps for exactly that.\n\nCREATE TABLE note_quality (\n  vault_id            TEXT NOT NULL,\n  path                TEXT NOT NULL,\n  computed_at         INTEGER NOT NULL,\n\n  -- Authored-side components (cache.db).\n  chunk_count         INTEGER NOT NULL DEFAULT 0,\n  dup_chunk_count     INTEGER NOT NULL DEFAULT 0,   -- chunks whose body_sha appears on another path\n  dup_ratio           REAL,                          -- NULL when body_sha is unavailable, not 0\n  mtime               INTEGER,\n  age_days            REAL,                          -- days since last EDIT (freshness.ts sense)\n\n  -- Usage-side components (experiential.db).\n  last_retrieved_at   INTEGER,\n  retrievals          INTEGER NOT NULL DEFAULT 0,\n  citations           INTEGER NOT NULL DEFAULT 0,\n  outcome_balance     INTEGER NOT NULL DEFAULT 0,\n\n  -- Graph-side components (cache.db vault_edges).\n  in_degree           INTEGER NOT NULL DEFAULT 0,\n  out_degree          INTEGER NOT NULL DEFAULT 0,\n  orphan              INTEGER NOT NULL DEFAULT 0,    -- 0/1: no edges in either direction\n\n  contradictions_open INTEGER NOT NULL DEFAULT 0,\n  tombstoned          INTEGER NOT NULL DEFAULT 0,    -- 0/1: a forget_log 'tombstone' names this path\n\n  quality_score       REAL,                          -- NULL == unmeasured; see the header\n  score_version       INTEGER NOT NULL DEFAULT 1,\n  flags               TEXT NOT NULL DEFAULT '[]',    -- JSON array, the human-readable summary\n\n  PRIMARY KEY (vault_id, path)\n);\n\n-- The report surface's ordering: worst-scoring first within a vault. NULLs sort separately and are\n-- filtered by flag, not by score.\nCREATE INDEX idx_note_quality_score ON note_quality(vault_id, quality_score);\nCREATE INDEX idx_note_quality_computed ON note_quality(computed_at DESC);\n",
  "20260727_001_session_client_info.sql": "-- THE-627: which client software opened this session.\n--\n-- Sourced from the MCP request's `_meta` key `io.modelcontextprotocol/clientInfo` (see\n-- src/mcp/client-info.ts), NOT from the `initialize` handshake — that handshake is removed in MCP\n-- 2026-07-28, while `_meta` works under both that spec and the current one.\n--\n-- Both columns are NULLABLE and stay NULL when the client sends nothing, which is the normal case\n-- today: no current client sends this key, and a placeholder like 'unknown' would be\n-- indistinguishable from a client that genuinely reports that name.\n--\n-- Deliberately NOT folded into the existing `metadata_json` column. That column holds\n-- CALLER-SUPPLIED session metadata from start_session's `session_metadata` argument; client identity\n-- is observed by the server from the transport. Mixing an observation into the caller's own bag\n-- would make the two indistinguishable downstream.\n--\n-- No index: these are read alongside a session row already located by id or by the existing\n-- (vault_id, started_at) index, never used as a lookup key.\n\nALTER TABLE workspace_sessions ADD COLUMN client_name TEXT;\nALTER TABLE workspace_sessions ADD COLUMN client_version TEXT;\n",
  "20260728_001_jobs_owner.sql": "-- 20260728_001_jobs_owner.sql\n-- THE-583: ownership columns on `jobs`, so the durable queue can back the MCP Tasks extension.\n--\n-- The 2026-07-28 revision moved Tasks out of the core protocol into an extension: a long-running\n-- call returns a task handle and the client polls `tasks/get` / drives `tasks/cancel`. The queue\n-- (THE-517) is the right substrate, but it could not be exposed as-is for two reasons, and the\n-- second is the important one:\n--\n--   1. There was no vault or caller column, so `tasks/get` against it would let ANY authenticated\n--      caller read ANY job by id — including `payload` and `last_error`, which carry vault paths\n--      and error text. In a multi-vault deployment that is a cross-vault read, the class THE-563 /\n--      THE-564 exist to prevent.\n--\n--   2. Every job in the table today is INTERNAL maintenance work — reconcile, contradiction,\n--      synthesis, audit, index-coordinator writes. No MCP caller asked for any of it. Surfacing\n--      those as \"your tasks\" would be wrong even with perfect isolation: they are not the caller's\n--      tasks, and their existence and failure text are server-operational detail.\n--\n-- Both columns are NULLABLE and NULL is the meaningful default: a job with no owner is internal and\n-- is NEVER visible over MCP. That makes the safe case the one you get by doing nothing — every\n-- existing row, and every existing `enqueue` call site, stays invisible without being touched.\n-- Visibility is opt-in at enqueue time, not opt-out at read time.\n\nALTER TABLE jobs ADD COLUMN vault_id TEXT;\nALTER TABLE jobs ADD COLUMN caller TEXT;\n\n-- Partial index: only owned rows are ever queried this way, and internal jobs (the overwhelming\n-- majority, and unbounded in number) are kept out of the index entirely.\nCREATE INDEX IF NOT EXISTS idx_jobs_owner\n  ON jobs(vault_id, caller, created_at DESC)\n  WHERE vault_id IS NOT NULL;\n",
  "20260728_002_jobs_outcome.sql": "-- 20260728_002_jobs_outcome.sql\n-- THE-583: persist a task-augmented call's OUTCOME, so `tasks/get` can return it.\n--\n-- Deferred result retrieval is the entire point of the Tasks extension: the client is handed a\n-- handle instead of an answer, and the answer has to be somewhere when it polls back. The ext-tasks\n-- schema makes that explicit — `CompletedTask.result` carries \"the result type of the original\n-- request\" (a CallToolResult here) and `FailedTask.error` carries the JSON-RPC error.\n--\n-- Until now the runner DISCARDED it. `runJob`'s handler signature returns void, so a task could\n-- reach `completed` carrying nothing at all — a client would poll, see success, and have no way to\n-- obtain what it asked for. That reads as a working feature right up to the moment someone tries to\n-- use the result.\n--\n-- ONE column holding a tagged envelope rather than two columns:\n--\n--   {\"ok\":true,  \"result\":{...}}                    -> CompletedTask.result\n--   {\"ok\":false, \"error\":{\"code\":N,\"message\":\"…\"}}  -> FailedTask.error\n--\n-- Two nullable columns would admit a row that is both and a row that is neither, and nothing would\n-- reject either state. The tag makes the two cases exclusive by construction, and NULL keeps its\n-- single meaning: no outcome recorded yet (still working, or an internal job that never has one).\n--\n-- Deliberately NOT reusing `last_error`: that column is operator-facing free text for retry\n-- diagnostics, and a client-facing JSON-RPC error object is a different contract with a different\n-- audience. Overloading it would put retry noise on the wire under a field the spec defines.\nALTER TABLE jobs ADD COLUMN outcome TEXT;\n",
  "20260729_001_gap_reports.sql": "-- THE-644 item 1: persist the gap-detector's GapReport so a pass can be read back later instead of\n-- recomputed. Precondition for the THE-611 read-only MCP tool (gap_report), which reads the latest\n-- row here rather than re-embedding + re-searching every query on every call.\n--\n-- It lives in experiential.db, not cache.db, for the same reason note_quality does (20260725_002):\n-- it is DERIVED and RESETTABLE, not authored vault content.\n--\n-- APPEND-ONLY, one row per pass — unlike note_quality's per-note upsert rollup, a gap report is a\n-- single run-level observation (a whole calibrated pass over a query set), and history across\n-- passes is itself useful (\"did this query stop being a gap?\"). The read side always wants the\n-- LATEST pass for a vault; older rows are kept for that history, not pruned here.\n--\n-- `items` is the GapReport.items array, JSON-encoded VERBATIM in the order detectGaps produced it\n-- (THE-616: input order, not sorted) — the report is diffed run-to-run, so preserving that order on\n-- the way into and out of storage matters as much as it does in the in-memory shape.\n\nCREATE TABLE gap_reports (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  vault_id     TEXT NOT NULL,\n  computed_at  INTEGER NOT NULL,\n  threshold    REAL NOT NULL,\n  min_results  INTEGER NOT NULL,\n  total        INTEGER NOT NULL,\n  gaps         INTEGER NOT NULL,\n  gap_rate     REAL NOT NULL,\n  items        TEXT NOT NULL   -- JSON array of GapItem, order-preserving\n);\n\n-- The read tool's access pattern: latest pass for a vault.\nCREATE INDEX idx_gap_reports_vault_computed ON gap_reports(vault_id, computed_at DESC);\n",
  "20260731_001_citation_state.sql": "-- 20260731_001_citation_state.sql\n-- The provenance axis on chunk_retrievals: WHY a citation verdict is what it is.\n--\n-- `cited_in_response` is a nullable 0/1 that today carries three different meanings in its `1`:\n--   * the gateway judge read the transcript and confirmed the chunk was used; and\n--   * the chunk merely passed the cheap stage-1 filter (ROUGE-L / cosine) and NO judge existed to\n--     check it -- citation.ts's \"stage-1-only mode\", reached whenever the gateway is unconfigured\n--     (cli/commands/citation-infer.ts: `judge: gwc ? ... : null`).\n-- Those are not the same claim. Passing a candidate filter is not proof of citation, so the\n-- absence of a judge currently MANUFACTURES citations, and nothing downstream can tell the two\n-- apart: chunk_access_stats, contribution.ts and metrics.ts all count `cited_in_response = 1`.\n--\n-- This column records the distinction. It is deliberately ADDITIVE and OBSERVATIONAL:\n-- `cited_in_response` keeps its exact current semantics and every existing number is unchanged.\n-- Whether a stage-1-only survivor should stop counting as a citation is a DATA-SEMANTICS decision\n-- with visible consequences for any gateway-less deployment, and this repo gates behaviour changes\n-- on evidence rather than on a refactor. Making the conflation queryable is the prerequisite for\n-- that decision, not the decision itself.\n--\n-- Vocabulary (NULL = never processed, matching cited_in_response's existing NULL, so no backfill):\n--   'confirmed' -- stage-2 judge affirmatively said cited.\n--   'rejected'  -- stage-1 negative, or the judge said not cited. Pairs with cited_in_response = 0.\n--   'candidate' -- passed stage 1, no judge available. Pairs with cited_in_response = 1 TODAY;\n--                  this is the row whose meaning is overstated, and the one a follow-up would\n--                  reconsider.\n--   'uncertain' -- RESERVED. The judge cannot express ambiguity yet (parseVerdict returns a\n--                  boolean), so nothing emits this. Declared here because widening the vocabulary\n--                  later would need another append-only migration, and the CHECK below has to\n--                  admit it from the start.\n--\n-- NULL stays legal: kill-switch rows deliberately stay unstamped for a clean rerun (see the\n-- >5% parse-failure abort in citation.ts), and every pre-existing row is NULL by construction.\nALTER TABLE chunk_retrievals ADD COLUMN citation_state TEXT\n  CHECK (citation_state IS NULL OR citation_state IN ('confirmed', 'rejected', 'candidate', 'uncertain'));\n",
  "20260802_001_acl_path_sets.sql": "-- 20260802_001_acl_path_sets.sql\n-- THE-694/695: the read-ACL predicate, made visible to SQLite.\n--\n-- Three retrieval paths compute an aggregate over the whole corpus and hand the result to a caller\n-- who can only see part of it. Fixing that needs the authorization boundary visible to SQL, which\n-- the cross-adapter Database interface cannot otherwise provide: bun:sqlite (what production runs)\n-- exposes no user-defined function registration at all — measured, not assumed — so a scalar\n-- predicate is not an option and a joinable table is.\n--\n-- PATH-keyed, not chunk-keyed: readableRel is a pure function of the path, so this holds 1,146 rows\n-- on the live vault rather than 13,486, and still serves chunks (join path), vault_edges (join\n-- source_path/target_path) and notes (join path).\n--\n-- The UNIQUE key deliberately EXCLUDES generation: a regenerated set replaces its predecessor in\n-- place, so growth is bounded by distinct ACL fingerprints rather than by index generations, which\n-- is what makes an LRU cap meaningful.\nCREATE TABLE IF NOT EXISTS acl_path_sets (\n  set_id          INTEGER PRIMARY KEY,\n  acl_fingerprint TEXT    NOT NULL,\n  vault_id        TEXT    NOT NULL,\n  generation      INTEGER NOT NULL,\n  built_at        INTEGER NOT NULL,\n  path_count      INTEGER NOT NULL,\n  UNIQUE (acl_fingerprint, vault_id)\n);\n\n-- The surrogate set_id exists for ROW SIZE. WITHOUT ROWID wants average rows under 1/20 of a page;\n-- page_size is 4096, so the budget is 204.8 bytes. Repeating the 64-char SHA-256 fingerprint on\n-- every member costs 165 bytes at the longest live path (81% of budget) and re-stores 71.6 KiB of\n-- identical hash. Interning gives 104 bytes worst case.\n--\n-- ON DELETE CASCADE is the PRIMARY safety control, not tidiness. Without AUTOINCREMENT, SQLite\n-- reuses a deleted rowid when the deleted row held the largest one — which is exactly what LRU\n-- eviction does when the cap binds. Reproduced with foreign_keys=OFF: evict the max-rowid set, its\n-- members are stranded, and the next caller is allocated the REUSED id and reads them. The eviction\n-- code ALSO deletes members explicitly, because foreign_keys is per-connection runtime state and\n-- correctness must not depend on a PRAGMA.\nCREATE TABLE IF NOT EXISTS acl_path_members (\n  set_id INTEGER NOT NULL REFERENCES acl_path_sets(set_id) ON DELETE CASCADE,\n  path   TEXT    NOT NULL,\n  PRIMARY KEY (set_id, path)\n) WITHOUT ROWID;\n",
  "20260803_001_preference_vault_id.sql": "-- 20260803_001_preference_vault_id.sql\n-- THE-710: namespace the preference plane by vault.\n--\n-- CORRECTION TO THE TICKET, recorded here because a migration is the permanent record. THE-710 says\n-- the THE-563/564 derived-plane namespacing \"skipped\" these tables. It did not. The global scope was\n-- DELIBERATE, audited under THE-562 P1.8, and documented in two places: the NAMESPACE comment above\n-- applyPreferenceDeltas, and SECURITY.md's \"Learned-state namespaces\" table (\"Global / shared\n-- runtime -- One learned preference profile for the runtime\"). This migration REVERSES that\n-- decision, on one axis only, and SECURITY.md is rewritten in the same change so the two stop\n-- disagreeing.\n--\n-- WHY REVERSE IT. The recorded rationale is \"correct for the single-user model\", and the residual\n-- SECURITY.md deliberately keeps open is a MULTI-PRINCIPAL one -- the `caller` axis. Single-user is\n-- not single-VAULT. With two vaults configured (this deployment runs `main` and `agents`), `key` as\n-- the entire primary key means a preference learned from one vault's episodes silently overwrites\n-- the same key learned from another's, and there is no column to filter on because none exists.\n-- That is the THE-310 defect class (vault_edges had no vault_id, so a cross-vault reconcile deleted\n-- another vault's edges) one layer up.\n--\n-- WHAT THIS DELIBERATELY DOES NOT DO. The caller axis stays an accepted residual: preferences remain\n-- shared across callers within a vault. Closing that too would make every reader caller-scoped and\n-- needs the P1.7 authorization treatment agent_episodes got, which is a larger change than this one.\n--\n-- PURGE, NOT BACKFILL -- and this contradicts THE-710's stated shape (\"backfill to the default\n-- vault\"). 20260724_001 (THE-563) set the test: purge when a table is REGENERABLE and its historical\n-- vault is UNRECOVERABLE. Preferences are both. reflect.ts re-extracts them from agent_episodes,\n-- which are retained; and no column ever recorded which vault a preference came from, so backfilling\n-- to a default would INVENT an attribution indistinguishable downstream from a measured one. Same\n-- disposition THE-310 (20260703_001) and THE-563 (20260724_001) took, for the same reason. On this\n-- deployment the purge is free -- both tables measured 0 rows on 2026-08-03 -- which is precisely\n-- why the rebuild is being done now rather than after THE-673 determinizes the extractor.\n\n-- preference_deltas: `id` is the primary key and is unaffected, so the column is added in place. The\n-- purge above is what makes NOT NULL satisfiable on an ALTER; no row is ever written with '',\n-- because applyPreferenceDeltas now takes vaultId as a REQUIRED argument rather than a defaulted one\n-- -- a default would silently reintroduce the blending this migration exists to stop.\nDELETE FROM preference_deltas;\nALTER TABLE preference_deltas ADD COLUMN vault_id TEXT NOT NULL DEFAULT '';\nCREATE INDEX IF NOT EXISTS idx_preference_deltas_vault ON preference_deltas(vault_id);\n\n-- preference_profile: `key` is the whole PRIMARY KEY and SQLite cannot alter one in place, so the\n-- table is dropped and recreated with vault_id LEADING the key -- the same shape 20260724_001 used\n-- for syntheses. Every other column definition is unchanged from 20260712_001.\nDROP TABLE preference_profile;\nCREATE TABLE preference_profile (\n  vault_id    TEXT NOT NULL,\n  key         TEXT NOT NULL,\n  value       TEXT NOT NULL,\n  weight      REAL NOT NULL DEFAULT 1.0,   -- confidence counter: capped [0, 5]; 0 = retracted\n  version     INTEGER NOT NULL,            -- monotonic batch version of the last touching delta\n  updated_at  INTEGER NOT NULL,            -- per-vault, not global: see applyPreferenceDeltas\n  provenance  TEXT,                        -- evidence gist from the extracting pass\n  PRIMARY KEY (vault_id, key)\n);\n",
  "20260803_002_goals.sql": "-- 20260803_002_goals.sql\n-- THE-633: stated goals — what the user is TRYING TO DO, as a first-class plane object.\n--\n-- The plane modelled preferences (\"you tend to X\") and had no notion of intent (\"you intend to X\").\n-- Those are not the same shape and a goal cannot be a preference row with a different key: a\n-- preference moves by WEIGHT (add/strengthen/weaken/retract) and never resolves; a goal moves by\n-- TERMINAL STATE (completed/abandoned/expired) and does. A shared `op` CHECK over both vocabularies\n-- would be the union of two disjoint sets, which is not a constraint at all. Hence its own table.\n--\n-- MEMBRANE DECISION (2026-08-03): goals live HERE, in experiential.db, with the trust boundary\n-- enforced on the WRITE PATH rather than by the file. The store's charter admits them — it holds\n-- \"NON-RECONSTRUCTABLE keep-state\", and a stated goal is exactly that, since it cannot be recomputed\n-- from the vault. And the membrane's actual mechanism is a FILE boundary preventing cross-store\n-- foreign keys (\"object_id / chunk_id reference chunk ids BY VALUE — this is the membrane\"), not a\n-- trust label attached to a store: a goals table here still cannot FK into an authored atom, so the\n-- property the membrane enforces is unchanged. Current practice in the field separates by write\n-- AUTHORITY, not by storage (Letta's read_only blocks, Mem0's infer:false verbatim path, OWASP\n-- ASI06's write-time admission + provenance binding). Precedent, too: preference_profile is\n-- user-shaped data and already lives here.\n--\n-- THE FOUR THINGS THE DECISION REQUIRES, and where each is enforced:\n--\n--   1. vault_id FROM THE FIRST MIGRATION. Not boilerplate — it is the one instruction that\n--      contradicts the nearest example in the codebase. preference_profile shipped without it and\n--      needed a rebuild (THE-710, 20260803_001) landed immediately before this file. Getting it\n--      right here is the whole reason that rebuild went first.\n--   2. `source` CHECK-pinned to stated provenance, so an INFERRED write is a CONSTRAINT VIOLATION\n--      rather than a convention someone can quietly break. Written as an IN-list with one member so\n--      widening it later is a deliberate migration, not an edit.\n--   3. Only the explicit set_goal / close_goal tools write this table. reflect.ts must never gain a\n--      goals write path — enforced by a grep gate in test/goals.test.ts, the same technique\n--      graph-analytics.test.ts uses to prove analytics never reaches ranking.\n--   4. Authority monotonicity: no low-confidence path may mutate a goal row. There is no\n--      strengthen/weaken here at all; the only transitions are open -> terminal.\n--\n-- GOALS EXPIRE, and expiry is a STATE not a delete. A goals table with no expiry silently becomes a\n-- list of things the user gave up on, biasing every downstream consumer toward stale intent. An\n-- overdue goal is marked 'expired' and kept, so the history survives and \"abandoned on purpose\" and\n-- \"ran out of time\" stay distinguishable.\n\nCREATE TABLE goals (\n  id          TEXT PRIMARY KEY,\n  vault_id    TEXT NOT NULL,\n  text        TEXT NOT NULL,\n  -- open is the only non-terminal state. completed/abandoned are user verdicts; expired is the\n  -- sweep's, and is deliberately distinct from abandoned.\n  status      TEXT NOT NULL DEFAULT 'open'\n              CHECK (status IN ('open', 'completed', 'abandoned', 'expired')),\n  -- Constraint 2. One member today; widening it is a migration, which is the point.\n  source      TEXT NOT NULL CHECK (source IN ('stated')),\n  created_at  INTEGER NOT NULL,\n  target_date INTEGER,\n  closed_at   INTEGER,\n  -- A terminal row without a closed_at, or an open row with one, is incoherent state. Enforced here\n  -- rather than in the writer so it holds for anything that ever touches this table.\n  CHECK ((status = 'open') = (closed_at IS NULL))\n);\n\n-- The read path is always \"this vault's goals, usually the open ones\".\nCREATE INDEX idx_goals_vault_status ON goals(vault_id, status);\n-- The expiry sweep's access pattern: open goals with a deadline, oldest first.\nCREATE INDEX idx_goals_due ON goals(target_date) WHERE target_date IS NOT NULL;\n",
};

/** The SQL for `file`. Throws rather than returning undefined: a missing migration must fail loudly
 *  at startup, not provision a partial schema that breaks later as "no such table". */
export function embeddedSql(file: string): string {
  const sql = EMBEDDED_MIGRATIONS[file];
  if (sql === undefined) {
    throw new Error(
      `migration "${file}" is not embedded — run \`bun run migrations:embed\` after adding it`,
    );
  }
  return sql;
}
